arguments.file_text:
namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A traditional Neapolitan pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = [
                "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            ],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp pancetta in a skillet over medium heat.",
                "Whisk eggs with grated Pecorino and plenty of black pepper.",
                "Drain pasta, reserving some cooking water.",
                "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.",
                "Add cooking water as needed for a creamy sauce."
            ],
            TotalRatings = 8, RatingSum = 38
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = [
                "Marinate chicken in yogurt and spices for at least 1 hour.",
                "Grill or broil chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in a large pan.",
                "Add tomato sauce and spices; simmer for 15 minutes.",
                "Stir in cream, then add the cooked chicken.",
                "Simmer 10 more minutes and serve with basmati rice."
            ],
            TotalRatings = 15, RatingSum = 70
        },
        new()
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Description = "Fragrant layered rice dish with mixed vegetables and aromatic spices.",
            Ingredients = ["Basmati rice", "Mixed vegetables", "Onions", "Saffron", "Whole spices", "Mint", "Cilantro", "Ghee"],
            Steps = [
                "Soak basmati rice for 30 minutes, then parboil until 70% cooked.",
                "Fry sliced onions until golden brown and set aside.",
                "Cook mixed vegetables with spices until tender.",
                "Layer rice and vegetables in a heavy-bottomed pot.",
                "Top with saffron milk, fried onions, and fresh herbs.",
                "Seal and cook on low heat for 20 minutes (dum style)."
            ],
            TotalRatings = 6, RatingSum = 27
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheese", "Sour cream", "Lime"],
            Steps = [
                "Brown ground beef in a skillet, breaking it into crumbles.",
                "Add taco seasoning and water; simmer until thickened.",
                "Warm corn tortillas in a dry skillet or over an open flame.",
                "Assemble tacos with beef, shredded lettuce, and diced tomato.",
                "Top with shredded cheese, sour cream, and a squeeze of lime."
            ],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Classic creamy avocado dip with fresh lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps = [
                "Halve and pit ripe avocados; scoop flesh into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in finely diced onion, jalapeño, and tomato.",
                "Add chopped cilantro, lime juice, and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            TotalRatings = 20, RatingSum = 92
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Chewy, buttery cookies loaded with chocolate chips.",
            Ingredients = ["Butter", "Brown sugar", "White sugar", "Eggs", "Vanilla", "Flour", "Baking soda", "Chocolate chips"],
            Steps = [
                "Cream butter with both sugars until light and fluffy.",
                "Beat in eggs and vanilla extract.",
                "Whisk together flour, baking soda, and salt; add to wet ingredients.",
                "Fold in chocolate chips.",
                "Drop rounded tablespoons onto baking sheets.",
                "Bake at 375°F (190°C) for 9–11 minutes until edges are golden."
            ],
            TotalRatings = 25, RatingSum = 118
        },
        new()
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Description = "Italian coffee-flavored layered dessert with mascarpone cream.",
            Ingredients = ["Ladyfinger biscuits", "Mascarpone", "Eggs", "Sugar", "Espresso", "Cocoa powder", "Marsala wine"],
            Steps = [
                "Brew espresso and let it cool; mix with Marsala wine.",
                "Separate eggs; whisk yolks with sugar until thick and pale.",
                "Fold mascarpone into the yolk mixture until smooth.",
                "Whip egg whites to stiff peaks and fold into mascarpone mixture.",
                "Dip ladyfingers briefly in espresso and layer in a dish.",
                "Spread mascarpone cream over the ladyfingers; repeat layers.",
                "Refrigerate at least 4 hours; dust with cocoa powder before serving."
            ],
            TotalRatings = 18, RatingSum = 85
        }
    ];

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

