@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — Recipe Community</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <span>@CategoryName</span>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
                    <span class="star-display">
                        @for (int i = 1; i <= 5; i++)
                        {
                            <span class="@(i <= Math.Round(recipe.AverageRating) ? "star filled" : "star")">★</span>
                        }
                    </span>
                    <span class="rating-text">@recipe.AverageRating.ToString("0.0") (@recipe.TotalRatings ratings)</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — Recipe Community</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <a href="/category/@Recipe.Category">@Recipe.Category</a> &rsaquo; <span>@Recipe.Title</span>
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>
        <p class="recipe-description">@Recipe.Description</p>

        <StarRating RecipeId="Recipe.Id" CurrentAverage="Recipe.AverageRating"
                    TotalRatings="Recipe.TotalRatings" OnRated="HandleRated" />

        <section class="recipe-section">
            <h2>Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>Steps</h2>
            <ol class="steps-list">
                @foreach (var step in Recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }
    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }

    private void HandleRated()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@inject RecipeService RecipeService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (Submitted)
{
    <div class="success-message">
        <h2>✅ Recipe submitted!</h2>
        <p>Your recipe "<strong>@Submission.Title</strong>" has been added.</p>
        <a href="/recipe/@NewRecipeId" class="btn btn-primary">View Your Recipe</a>
        <button class="btn btn-secondary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" class="recipe-form" FormName="submitRecipe">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="Submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="Submission.Category">
                <option value="">— Select a category —</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Submission.Steps" rows="6"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
        </div>

        <button type="submit" class="btn btn-primary"
                disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }
    private int NewRecipeId { get; set; }

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(Submission);
        NewRecipeId = recipe.Id;
        Submitted = true;
    }

    private void Reset()
    {
        Submission = new();
        Submitted = false;
    }
}

@rendermode InteractiveServer

<div class="star-rating-widget">
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= (HoverStar ?? SelectedStar) ? "active" : "")"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => HoverStar = star"
                    @onmouseout="() => HoverStar = null"
                    disabled="@HasRated"
                    title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
                ★
            </button>
        }
    </div>
    <span class="rating-info">
        @if (HasRated)
        {
            <span>You rated this @SelectedStar star@(SelectedStar > 1 ? "s" : "") · </span>
        }
        @CurrentAverage.ToString("0.0") avg (@TotalRatings ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }
    [Parameter] public EventCallback OnRated { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int? HoverStar { get; set; }
    private int SelectedStar { get; set; }
    private bool HasRated { get; set; }

    private async Task Rate(int stars)
    {
        if (HasRated) return;

        SelectedStar = stars;
        HasRated = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }

        await OnRated.InvokeAsync();
    }
}

